{
  "moms": [
    {
      "name": "The Lady Who Sold Her Cat",
      "role": "The Cat's Very Best Friend",
      "note": "She was so kind to a cat that it turned into her best friend, then she sold it. She is now known as 'Lady'."
    },
    {
      "name": "Mom who Made the Soup",
      "role": "The Soup Monster",
      "note": "Her son ate all the soup he could find and found himself hungry again. Now, she is famous for making soup with a face on it."
    },
    {
      "name": "The Mother of the Mummy",
      "role": "The Ancient Ghost",
      "note": "She was a mummy in the past and now lives in a ghost town where she can still see ghosts from the future."
    },
    {
      "name": "The One Who Wore a Hat",
      "role": "The Head of the House",
      "note": "Everyone thinks she wears a hat because she has a very high opinion of herself. She actually owns a lot of hats though."
    },
    {
      "name": "Mom Who Forgot Her Name",
      "role": "The Unnamed Sister",
      "note": "She never had a name and everyone assumed she was named after something else. But nobody knew until today."
    }
  ]
}

{
  "nickname": "The Rusty Knight"
}
